import{_ as i,o as t,c as e,a3 as l}from"./chunks/framework.D1iekJsc.js";const k=JSON.parse('{"title":"開啟局域網訪問（Ollama）","description":"設置 OLLAMA_HOST=0.0.0.0 與防火牆，讓手機 MiniTavern 通過局域網訪問電腦上的 Ollama。","frontmatter":{"title":"開啟局域網訪問（Ollama）","description":"設置 OLLAMA_HOST=0.0.0.0 與防火牆，讓手機 MiniTavern 通過局域網訪問電腦上的 Ollama。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"開啟局域網訪問（Ollama） · MiniTavern Docs"}],["meta",{"property":"og:description","content":"設置 OLLAMA_HOST=0.0.0.0 與防火牆，讓手機 MiniTavern 通過局域網訪問電腦上的 Ollama。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/ollama/lan"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/ollama/lan"}]]},"headers":[],"relativePath":"zh-TW/ollama/lan.md","filePath":"zh-TW/ollama/lan.md","lastUpdated":1787224147000}'),s={name:"zh-TW/ollama/lan.md"};function n(o,a,h,r,p,d){return t(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="開啟局域網訪問-ollama" tabindex="-1">開啟局域網訪問（Ollama） <a class="header-anchor" href="#開啟局域網訪問-ollama" aria-label="Permalink to &quot;開啟局域網訪問（Ollama）&quot;">​</a></h1><p>默認情況下，Ollama 往往只監聽本機。手機要連電腦，必須讓服務監聽 <strong>所有網卡</strong>（<code>0.0.0.0</code>），並放行防火牆端口。</p><h2 id="設置-ollama-host" tabindex="-1">設置 <code>OLLAMA_HOST</code> <a class="header-anchor" href="#設置-ollama-host" aria-label="Permalink to &quot;設置 `OLLAMA_HOST`&quot;">​</a></h2><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ol><li>在開始菜單搜索「環境變量」→「編輯系統環境變量」→「環境變量」。</li><li>在「用戶變量」或「系統變量」中新建：</li></ol><table tabindex="0"><thead><tr><th>變量名</th><th>變量值</th></tr></thead><tbody><tr><td><code>OLLAMA_HOST</code></td><td><code>0.0.0.0</code></td></tr></tbody></table><ol start="3"><li>確定保存後，<strong>完全退出並重新打開</strong> Ollama（托盤圖標退出再啟動）。</li></ol><p>也可在 PowerShell（當前會話臨時生效）中：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OLLAMA_HOST </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;0.0.0.0&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 然後重啟 ollama 應用或服務</span></span></code></pre></div><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>臨時（當前終端會話）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">launchctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setenv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OLLAMA_HOST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><p>然後退出並重新打開 Ollama 應用。若重啟後失效，可寫入 shell 配置或使用 LaunchAgent；也可用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OLLAMA_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0.0.0</span></span></code></pre></div><p>並確保 Ollama 服務在該環境下啟動。最穩妥仍是：<strong>設置環境變量後重啟 Ollama</strong>。</p><h2 id="防火牆放行端口-11434" tabindex="-1">防火牆放行端口 11434 <a class="header-anchor" href="#防火牆放行端口-11434" aria-label="Permalink to &quot;防火牆放行端口 11434&quot;">​</a></h2><ul><li><strong>Windows</strong>：系統設置 → 隱私和安全性 → Windows 安全中心 → 防火牆 → 允許應用通過防火牆；或新建入站規則放行 TCP <code>11434</code>。</li><li><strong>macOS</strong>：系統設置 → 網絡 → 防火牆；首次訪問時允許 Ollama，或對端口放行。</li></ul><h2 id="驗證局域網" tabindex="-1">驗證局域網 <a class="header-anchor" href="#驗證局域網" aria-label="Permalink to &quot;驗證局域網&quot;">​</a></h2><ol><li>查電腦 IP（見 <a href="./../quickstart#step-4查電腦局域網-ip">快速開始 Step 4</a>）。</li><li>用<strong>同一 Wi‑Fi 下另一臺設備</strong>的瀏覽器訪問：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://YOUR_PC_IP:11434</span></span></code></pre></div><p>能打開或返回 Ollama 相關響應，說明局域網已通。</p><h2 id="給-minitavern-用的地址" tabindex="-1">給 MiniTavern 用的地址 <a class="header-anchor" href="#給-minitavern-用的地址" aria-label="Permalink to &quot;給 MiniTavern 用的地址&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://YOUR_PC_IP:11434/v1</span></span></code></pre></div><p>注意：</p><ul><li>用局域網 IP，<strong>不要</strong>用 <code>localhost</code></li><li>建議帶 <code>/v1</code> 後綴（OpenAI 兼容路徑）</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="./../connect-app/minitavern">在 MiniTavern 中配置</a></p>',27)])])}const m=i(s,[["render",n]]);export{k as __pageData,m as default};
